package com.habilitesrandom;
import com.habilitesrandom.api.TransformationDefinition;import com.habilitesrandom.data.PlayerProfile;import com.habilitesrandom.transformation.PowerfulFormService;import org.junit.jupiter.api.*;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class PowerfulFormServiceTest {
 private final TransformationDefinition form=new TransformationDefinition(HabilitesRandom.id("test_form"),"Test","",200,1200,1.5,1.2,1.2,List.of(),"minecraft:flash","minecraft:item.totem.use");
 @Test void oneUsePerOverworldDayAndSleepReset(){var p=withCharacter(PlayerProfile.empty(1));var used=PowerfulFormService.activate(p,form,100,1_000);assertEquals(0,PowerfulFormService.availability(used,100,20_000).remaining());assertThrows(IllegalStateException.class,()->PowerfulFormService.activate(PowerfulFormService.finish(used),form,100,30_000));assertEquals(1,PowerfulFormService.availability(used,101,30_000).remaining());assertEquals(101,PowerfulFormService.overworldDay(101*24000L));}
 @Test void fruitAllowsExactlyTwoAndDoesNotStack(){var p=PowerfulFormService.consumeFruit(withCharacter(PlayerProfile.empty(1)));assertThrows(IllegalStateException.class,()->PowerfulFormService.consumeFruit(p));var one=PowerfulFormService.finish(PowerfulFormService.activate(p,5,100));var two=PowerfulFormService.finish(PowerfulFormService.activate(one,form,5,20_000));assertEquals(0,PowerfulFormService.availability(two,5,40_000).remaining());assertThrows(IllegalStateException.class,()->PowerfulFormService.activate(two,form,5,40_000));}
 @Test void deathRelogAndRerollCanFinishWithoutRefund(){var p=PowerfulFormService.activate(withCharacter(PlayerProfile.empty(1)),form,7,100);var finished=PowerfulFormService.finish(p);assertFalse(PowerfulFormService.availability(finished,7,200).active());assertEquals(0,PowerfulFormService.availability(finished,7,200).remaining());}
 private PlayerProfile withCharacter(PlayerProfile p){return p.withIdentity(new PlayerProfile.Identity("habilitesrandom:goku","habilitesrandom:dragon_ball","habilitesrandom:divine","strong","Strong")).withLoadout(new PlayerProfile.Loadout(List.of("a","b","c","d"),form.id().toString(),0,false,0,0,-1,0));}
}
